(() => {
  try {
    const text = document.body.innerText;
    const stats = {};

    // 更精确的基础数据提取
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);

    // Money
    for (const line of lines) {
      if (line.includes('元') && /\d/.test(line)) {
        const m = line.match(/([\d,]+)\s*元/);
        if (m) { stats.money = m[1].replace(/,/g, ''); break; }
      }
    }

    // Stamina/Health - find lines with specific patterns
    for (const line of lines) {
      if (line.includes('⚡') && line.includes('/')) {
        const m = line.match(/(\d+)\s*\/\s*(\d+)/);
        if (m) stats.stamina = m[1] + '/' + m[2];
      }
      if (line.includes('❤️') && line.includes('/')) {
        const m = line.match(/(\d+)\s*\/\s*(\d+)/);
        if (m) stats.health = m[1] + '/' + m[2];
      }
    }

    // 从localStorage获取存档
    const allKeys = Object.keys(localStorage);
    const farmKeys = allKeys.filter(k => k.toLowerCase().includes('farm') || k.toLowerCase().includes('save') || k.toLowerCase().includes('game'));
    stats.localStorageKeys = farmKeys;

    let saveData = null;
    for (const key of farmKeys) {
      try {
        const val = localStorage.getItem(key);
        if (val && val.length > 50) {
          const parsed = JSON.parse(val);
          saveData = parsed;
          stats.saveKey = key;
          break;
        }
      } catch(e) {}
    }

    if (saveData) {
      stats.hasSaveData = true;
      stats.saveDay = saveData.day;
      stats.saveSeason = saveData.season;
      stats.saveMoney = saveData.money;
      stats.saveStamina = saveData.stamina;
      stats.saveHealth = saveData.health;
      stats.saveFields = saveData.fields ? saveData.fields.length : 0;
      stats.saveNPC = saveData.npcFavor || saveData.npc || {};
      stats.saveSkills = saveData.skills || {};
      stats.saveEvents = saveData.events ? saveData.events.length : 0;
      stats.saveInventory = saveData.inventory || {};
    } else {
      stats.hasSaveData = false;
    }

    return JSON.stringify(stats);
  } catch(e) {
    return JSON.stringify({error: e.message, stack: e.stack});
  }
})()
